with with_dims as (select a.*, p.discount, p.status as order_status from payments a left join orders p on a.order_id = p.id), scored as (select *, ntile(5) over w_recent as discount_bucket, sum(discount) over (partition by order_status order by paid_at asc, id asc rows between unbounded preceding and current row) as running_discount from with_dims window w_recent as (partition by status order by discount asc, id asc)), with_windows as (select *, sum(running_discount) over (partition by order_id order by discount asc, id asc rows between unbounded preceding and current row) as running_running_discount, avg(discount) over w_grp as discount_avg_30d, lag(discount, 1, 0) over w_hist as prev_discount from scored window w_grp as (partition by order_status order by cast(paid_at as bigint) asc range between 2592000 preceding and current row), w_hist as (partition by status order by running_discount asc, id asc)), enriched as (select id, order_id, method, amount, paid_at, status, discount, order_status, discount_bucket, running_discount, running_running_discount, discount_avg_30d, prev_discount, ntile(5) over (partition by method order by prev_discount asc, id asc) as prev_discount_bucket, dense_rank() over (order by amount desc) as amount_dense_rank, avg(discount_avg_30d) over w_hist as discount_avg_30d_avg_6_prior from with_windows window w_hist as (partition by order_status order by discount asc, id asc rows between 6 preceding and 1 preceding)) select date_trunc('week', paid_at) as week_start, case when prev_discount_bucket >= 8 then 'HIGH' else 'LOW' end as prev_discount_bucket_tier, round(avg(amount_dense_rank), 2) as avg_amount_dense_rank, count(*) as num_rows, avg(discount_bucket) as avg_discount_bucket, size(collect_set(status)) as num_status, size(collect_set(status)) as num_status_2, sum(case when status = 'SUCCESS' then amount_dense_rank else 0 end) as success_amount_dense_rank from enriched group by grouping sets ((date_trunc('week', paid_at), case when prev_discount_bucket >= 8 then 'HIGH' else 'LOW' end), (date_trunc('week', paid_at)), ());
